int gin_factory_bank_load(unsigned index,gin_factory_kit_t *out) {
unsigned i,j,side,n; unsigned char *zero; if(!out||index>=GIN_FACTORY_BANK_COUNT)return -1;
zero=(unsigned char *)out; for(n=0;n<sizeof(*out);++n)zero[n]=0;out->count=24;
for(i=0;i<24;++i){out->sounds[i].id=1000u+i;for(j=0;j<24;++j)out->sounds[i].name[j]=gin_factory_bank[index].sound_name[i][j];
for(side=0;side<2;++side){const float *p=(const float *)&gin_factory_bank[index].patch[i][side];for(j=0;j<21;++j)out->sounds[i].endpoint[side][j]=p[j];}}
for(i=0;i<24;++i)out->key_map[i]=gin_factory_bank[index].key_map[i];return 0;}
